/** @jsxRuntime classic */
/** @jsx React.createElement */
import React, { type ComponentType } from 'react';

import type { JSX } from 'react/jsx-runtime';

/**
 * Options for creating a component with defaults.
 */
export interface CreateComponentOptions<P> {
  /** Component to wrap */
  component: ComponentType<P>;
  /** Default props to apply */
  defaultProps: Partial<P>;
  /** Display name for the wrapped component */
  displayName?: string;
}

/**
 * Creates a component with default props applied.
 *
 * This is useful for creating variants of components with preset
 * configurations while maintaining full type safety.
 *
 * **Key Features**:
 * - Type-safe default props
 * - Preserves component types
 * - Custom display names
 * - Shallow merge of props
 *
 * @param options - Component configuration
 * @returns Component with defaults applied
 *
 * @example
 * ```tsx
 * // Create button variants
 * import { Button } from './Button';
 *
 * export const PrimaryButton = createComponent({
 *   component: Button,
 *   defaultProps: {
 *     variant: 'primary',
 *     size: 'medium',
 *   },
 *   displayName: 'PrimaryButton',
 * });
 *
 * export const SecondaryButton = createComponent({
 *   component: Button,
 *   defaultProps: {
 *     variant: 'secondary',
 *     size: 'medium',
 *   },
 *   displayName: 'SecondaryButton',
 * });
 *
 * // Usage
 * <PrimaryButton onClick={handleClick}>Click me</PrimaryButton>
 * ```
 *
 * @example
 * ```tsx
 * // Create styled input
 * const EmailInput = createComponent({
 *   component: Input,
 *   defaultProps: {
 *     type: 'email',
 *     autoComplete: 'email',
 *     placeholder: 'Enter your email',
 *   },
 *   displayName: 'EmailInput',
 * });
 * ```
 */
export function createComponent<P extends object>({
  component: Component,
  defaultProps,
  displayName,
}: CreateComponentOptions<P>): ComponentType<P> {
  const WrappedComponent = (props: P): JSX.Element => {
    // Merge default props with provided props (provided props take precedence)
    const mergedProps = { ...defaultProps, ...props } as P;
    return React.createElement(Component, mergedProps);
  };

  // Set display name for debugging
  WrappedComponent.displayName =
    displayName || `WithDefaults(${Component.displayName || Component.name || 'Component'})`;

  return WrappedComponent;
}

import { createContext as createReactContext, useContext } from 'react';

import { invariant } from './invariant';

/**
 * Options for creating a context.
 */
export interface StrictContextOptions<T> {
  /** Name of the context for debugging */
  name: string;
  /** Default value (optional) */
  defaultValue?: T;
  /** Error message when context is used outside provider */
  errorMessage?: string;
  /** Whether to allow usage outside provider (requires defaultValue) */
  strict?: true;
}

export interface NonStrictContextOptions<T> {
  /** Name of the context for debugging */
  name: string;
  /** Default value (required when strict is false) */
  defaultValue: T;
  /** Error message when context is used outside provider */
  errorMessage?: string;
  /** Whether to allow usage outside provider (requires defaultValue) */
  strict: false;
}

export type CreateContextOptions<T> = StrictContextOptions<T> | NonStrictContextOptions<T>;

/**
 * Return type of createContext.
 */
export interface ContextReturn<T> {
  /** The React Context object */
  Context: React.Context<T | undefined>;
  /** Hook to consume the context */
  useContext: () => T;
  /** Provider component */
  Provider: React.Provider<T | undefined>;
}

/**
 * Creates a type-safe React context with automatic provider validation.
 *
 * This eliminates the need for null checks when consuming context and
 * provides better error messages when context is used incorrectly.
 *
 * **Key Features**:
 * - Type-safe context consumption
 * - Automatic provider validation
 * - Custom error messages
 * - Named contexts for debugging
 * - Optional strict mode
 *
 * @param options - Context configuration
 * @returns Context object with Provider and hook
 *
 * @example
 * ```tsx
 * // Create theme context
 * interface ThemeContextValue {
 *   mode: 'light' | 'dark';
 *   toggleMode: () => void;
 * }
 *
 * const { Provider: ThemeProvider, useContext: useTheme } = createContext<ThemeContextValue>({
 *   name: 'Theme',
 *   errorMessage: 'useTheme must be used within ThemeProvider',
 * });
 *
 * function App() {
 *   const [mode, setMode] = useState<'light' | 'dark'>('light');
 *
 *   return (
 *     <ThemeProvider value={{ mode, toggleMode: () => setMode(m => m === 'light' ? 'dark' : 'light') }}>
 *       <Content />
 *     </ThemeProvider>
 *   );
 * }
 *
 * function Content() {
 *   const { mode, toggleMode } = useTheme(); // No null checks needed!
 *   return <button onClick={toggleMode}>{mode}</button>;
 * }
 * ```
 *
 * @example
 * ```tsx
 * // With default value (non-strict mode)
 * const { Provider, useContext: useConfig } = createContext({
 *   name: 'Config',
 *   defaultValue: { apiUrl: '/api' },
 *   strict: false,
 * });
 *
 * // Can be used without provider
 * function Component() {
 *   const config = useConfig(); // Returns default value
 *   return <div>{config.apiUrl}</div>;
 * }
 * ```
 */
export function createContext<T>(options: CreateContextOptions<T>): ContextReturn<T> {
  const {
    name,
    defaultValue,
    errorMessage = `use${name} must be used within ${name}Provider`,
    strict = true,
  } = options;

  const Context = createReactContext<T | undefined>(defaultValue);
  Context.displayName = name;

  function useContextHook(): T {
    const context = useContext(Context);

    if (strict && context === undefined) {
      invariant(false, errorMessage);
      // Fallback return to satisfy TypeScript after invariant throws
      return defaultValue as T;
    }

    // If not strict and context is undefined, use default value
    if (!strict && context === undefined) {
      invariant(
        defaultValue !== undefined,
        `${name} context: defaultValue must be provided when strict is false`
      );
      return defaultValue as T;
    }

    // Non-strict path or provided context value
    invariant(context !== undefined, errorMessage);
    return context;
  }

  return {
    Context,
    useContext: useContextHook,
    Provider: Context.Provider,
  };
}

import type { ComponentPropsWithRef, ElementType } from 'react';
import type { JSX } from 'react/jsx-runtime';

/**
 * Props for polymorphic components.
 *
 * Allows components to render as different HTML elements or components
 * while maintaining type safety for props.
 */
export type PolymorphicProps<E extends ElementType, P = object> = P & {
  /** Element type to render as */
  as?: E;
} & Omit<ComponentPropsWithRef<E>, keyof P | 'as'>;

/**
 * Polymorphic component type.
 */
export type PolymorphicComponent<DefaultElement extends ElementType, P = object> = <
  E extends ElementType = DefaultElement,
>(
  props: PolymorphicProps<E, P>
) => JSX.Element | null;

/**
 * Creates a polymorphic component that can render as different elements.
 *
 * This enables the "as" prop pattern popularized by libraries like
 * Chakra UI and Radix UI, allowing components to be flexible while
 * maintaining full type safety.
 *
 * **Key Features**:
 * - Type-safe "as" prop
 * - Preserves element-specific props
 * - Automatic ref forwarding
 * - Display name support
 *
 * @param defaultElement - Default element to render
 * @param displayName - Component display name
 * @returns Polymorphic component factory
 *
 * @example
 * ```tsx
 * // Create a polymorphic Text component
 * interface TextProps {
 *   variant?: 'body' | 'heading' | 'caption';
 *   weight?: 'normal' | 'bold';
 * }
 *
 * const Text = createPolymorphic<'span', TextProps>('span', 'Text')(
 *   ({ as: Element = 'span', variant = 'body', weight = 'normal', ...props }) => {
 *     return (
 *       <Element
 *         {...props}
 *         className={cn(
 *           'text',
 *           `text-${variant}`,
 *           `text-${weight}`,
 *           props.className
 *         )}
 *       />
 *     );
 *   }
 * );
 *
 * // Usage with different elements
 * <Text>Default span</Text>
 * <Text as="p">Paragraph</Text>
 * <Text as="h1" variant="heading">Heading</Text>
 * <Text as="a" href="/link">Link with href prop!</Text>
 * ```
 *
 * @example
 * ```tsx
 * // Polymorphic Button
 * interface ButtonProps {
 *   variant?: 'primary' | 'secondary';
 *   size?: 'sm' | 'md' | 'lg';
 * }
 *
 * const Button = createPolymorphic<'button', ButtonProps>('button', 'Button')(
 *   ({ as: Element = 'button', variant = 'primary', size = 'md', ...props }) => {
 *     return (
 *       <Element
 *         {...props}
 *         className={cn('btn', `btn-${variant}`, `btn-${size}`, props.className)}
 *       />
 *     );
 *   }
 * );
 *
 * // Can render as button or link
 * <Button onClick={handleClick}>Button</Button>
 * <Button as="a" href="/path">Link Button</Button>
 * ```
 */
export function createPolymorphic<DefaultElement extends ElementType, P = object>(
  _defaultElement: DefaultElement,
  displayName?: string
) {
  return function createComponent(
    render: (props: PolymorphicProps<DefaultElement, P>) => JSX.Element | null
  ): PolymorphicComponent<DefaultElement, P> {
    const Component = render as PolymorphicComponent<DefaultElement, P> & {
      displayName?: string;
    };

    if (displayName) {
      Component.displayName = displayName;
    }

    return Component;
  };
}

import type { ComponentType } from 'react';

/**
 * Gets the display name of a React component.
 *
 * Useful for debugging, error messages, and developer tools.
 * Checks displayName, name, and falls back to 'Component'.
 *
 * **Key Features**:
 * - Checks displayName property
 * - Falls back to function name
 * - Default for anonymous components
 * - Type-safe
 *
 * @param Component - React component
 * @returns Display name string
 *
 * @example
 * ```tsx
 * function withLogging<P extends object>(Component: ComponentType<P>) {
 *   const displayName = getDisplayName(Component);
 *
 *   return function WithLogging(props: P) {
 *     console.log(`Rendering ${displayName}`);
 *     return <Component {...props} />;
 *   };
 * }
 * ```
 *
 * @example
 * ```tsx
 * // In error messages
 * function validateProps<P>(Component: ComponentType<P>, props: P) {
 *   if (!props) {
 *     throw new Error(
 *       `${getDisplayName(Component)}: props cannot be undefined`
 *     );
 *   }
 * }
 * ```
 */
export function getDisplayName<P = Record<string, unknown>>(
  Component: ComponentType<P> | null | undefined
): string {
  if (!Component) {
    return 'Component';
  }

  // Check displayName property (manually set)
  if (Component.displayName) {
    return Component.displayName;
  }

  // Check function name
  if (Component.name) {
    return Component.name;
  }

  // Fallback for anonymous components
  return 'Component';
}

export { getDisplayName } from './getDisplayName';
export { invariant } from './invariant';
export { isDev } from './isDev';
export { warn } from './warn';
export { clearWarnings, warnOnce } from './warnOnce';

export { createContext } from './createContext';
export type { ContextReturn, CreateContextOptions } from './createContext';

export { createComponent } from './createComponent';
export type { CreateComponentOptions } from './createComponent';

export { createPolymorphic } from './createPolymorphic';
export type { PolymorphicComponent, PolymorphicProps } from './createPolymorphic';

/**
 * Asserts that a condition is true, throwing an error if it's false.
 *
 * This is useful for runtime assertions that should always be true.
 * The function throws in both development and production, unlike warn/warnOnce.
 *
 * **Key Features**:
 * - Type narrowing via assertion
 * - Descriptive error messages
 * - Stack trace preservation
 * - Production-safe (throws real errors)
 *
 * @param condition - Condition that must be true
 * @param message - Error message if condition is false
 * @throws {Error} If condition is false
 *
 * @example
 * ```tsx
 * function getUser(id: string | null): User {
 *   invariant(id !== null, 'User ID cannot be null');
 *
 *   // TypeScript knows id is string here
 *   return fetchUser(id);
 * }
 * ```
 *
 * @example
 * ```tsx
 * // With type narrowing
 * function processValue(value: string | number) {
 *   invariant(typeof value === 'string', 'Expected string value');
 *
 *   // TypeScript knows value is string here
 *   return value.toUpperCase();
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Array bounds checking
 * function getFirst<T>(items: T[]): T {
 *   invariant(items.length > 0, 'Array must not be empty');
 *
 *   return items[0];
 * }
 * ```
 */
export function invariant(condition: unknown, message: string): asserts condition {
  if (!condition) {
    throw new Error(`Invariant violation: ${message}`);
  }
}

/**
 * Detects if the code is running in development mode.
 *
 * Checks NODE_ENV and common development indicators.
 * This is useful for conditional warnings, debugging, and feature flags.
 *
 * **Key Features**:
 * - Checks NODE_ENV
 * - Detects __DEV__ global
 * - SSR-safe
 * - Cached result
 *
 * @returns True if in development mode
 *
 * @example
 * ```tsx
 * function Component({ value }: Props) {
 *   if (isDev() && !value) {
 *     console.warn('Component: value prop is undefined');
 *   }
 *
 *   return <div>{value}</div>;
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Conditional debug logging
 * function processData(data: unknown) {
 *   if (isDev()) {
 *     console.log('Processing data:', data);
 *   }
 *
 *   // ... processing logic
 * }
 * ```
 */
interface GlobalWithDev {
  __DEV__?: boolean;
}

export function isDev(): boolean {
  try {
    // Check NODE_ENV
    if (typeof process !== 'undefined' && process?.env?.['NODE_ENV']) {
      return process.env['NODE_ENV'] === 'development';
    }
  } catch {
    // Guard against ReferenceError in runtimes without process
    return false;
  }

  // Check __DEV__ global (used by React Native and some bundlers)
  if (typeof globalThis !== 'undefined' && '__DEV__' in globalThis) {
    return (globalThis as GlobalWithDev).__DEV__ === true;
  }

  // Default to false (production-safe)
  return false;
}

import { isDev } from './isDev';

/**
 * Logs a warning message in development mode only.
 *
 * This function is tree-shakeable in production builds when used
 * with proper bundler configuration.
 *
 * **Key Features**:
 * - Development-only warnings
 * - Tree-shakeable in production
 * - Preserves stack traces
 * - Component-friendly formatting
 *
 * @param message - Warning message to display
 * @param component - Optional component name for context
 *
 * @example
 * ```tsx
 * function Button({ onClick, disabled }: ButtonProps) {
 *   if (!onClick && !disabled) {
 *     warn('Button has no onClick handler and is not disabled', 'Button');
 *   }
 *
 *   return <button onClick={onClick} disabled={disabled}>Click</button>;
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Deprecation warning
 * function OldAPI(value: string) {
 *   warn('OldAPI is deprecated. Use NewAPI instead.');
 *   return value.toUpperCase();
 * }
 * ```
 */
export function warn(message: string, component?: string): void {
  if (!isDev()) {
    return;
  }

  const prefix = component ? `[${component}]` : '[Warning]';

  // Use console.warn to preserve stack trace
  console.warn(`${prefix} ${message}`);
}

import { isDev } from './isDev';

/**
 * Cache for warnings that have been shown.
 */
const warnedMessages = new Set<string>();

/**
 * Logs a warning message once per unique key in development mode.
 *
 * Useful for warnings that might be triggered many times but should
 * only be shown once to avoid console spam.
 *
 * **Key Features**:
 * - Development-only warnings
 * - Deduplication by key
 * - Tree-shakeable in production
 * - Preserves stack traces
 *
 * @param key - Unique key for this warning
 * @param message - Warning message to display
 * @param component - Optional component name for context
 *
 * @example
 * ```tsx
 * function DataTable({ data }: Props) {
 *   data.forEach((item) => {
 *     if (!item.id) {
 *       warnOnce('missing-id', 'DataTable items should have an id property', 'DataTable');
 *     }
 *   });
 *
 *   return <table>...</table>;
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Deprecation warning shown once
 * function useOldHook() {
 *   warnOnce(
 *     'use-old-hook-deprecated',
 *     'useOldHook is deprecated. Use useNewHook instead.'
 *   );
 *
 *   return {};
 * }
 * ```
 */
export function warnOnce(
  key: string,
  message: string,
  componentOrOptions?: string | { namespace?: string }
): void {
  if (!isDev()) {
    return;
  }

  // Empty keys: treat as always warn (no dedup) to avoid silent suppression
  if (key === '') {
    const prefix = typeof componentOrOptions === 'string' ? `[${componentOrOptions}]` : '[Warning]';
    console.warn(`${prefix} ${message}`);
    return;
  }

  let component: string | undefined;
  let namespace = '';

  if (typeof componentOrOptions === 'string') {
    component = componentOrOptions;
  } else if (componentOrOptions?.namespace) {
    namespace = componentOrOptions.namespace;
  }

  const cacheKey = namespace ? `${namespace}:${key}` : key;

  if (warnedMessages.has(cacheKey)) {
    return;
  }

  warnedMessages.add(cacheKey);

  const prefix = component ? `[${component}]` : '[Warning]';

  // Use console.warn to preserve stack trace
  console.warn(`${prefix} ${message}`);
}

/**
 * Clears the warning cache.
 *
 * Useful for testing or resetting warning state.
 *
 * @example
 * ```tsx
 * // In tests
 * afterEach(() => {
 *   clearWarnings();
 * });
 * ```
 */
export function clearWarnings(): void {
  warnedMessages.clear();
}
